    @Test void nullAndNegativeCountsAreRejected() {
        assertThrows(IllegalArgumentException.class, () -> ActivityDiffService.diff(T, Map.of("minecraft:diamond", null), Map.of()));
        assertThrows(IllegalArgumentException.class, () -> ActivityDiffService.diff(T, Map.of("minecraft:diamond", -1L), Map.of()));
        assertThrows(IllegalArgumentException.class, () -> ActivityDiffService.diff(T, Map.of(), Map.of("minecraft:diamond", null)));
