        assertEquals(List.of("minecraft:diamond"), events.get(0).registryIds());
        assertEquals(ActivityEvent.Type.ITEM_LOST, events.get(0).type());
        assertEquals(1L, events.get(0).quantity());
    }"
    }
  ],
  "risks": []
}

